  1445|const SB_HARD_TIMEOUT_MS = 6_000;
  1446|async function withTimeout<T extends Response>(handler: () => Promise<T>, fallback: () => Response): Promise<Response> {
  1447|  let timer: ReturnType<typeof setTimeout> | undefined;
  1448|  const timeoutPromise = new Promise<Response>((resolve) => {
  1449|    timer = setTimeout(() => resolve(fallback()), SB_HARD_TIMEOUT_MS);
  1450|  });
  1451|  try {
  1452|    return await Promise.race([handler(), timeoutPromise]);
  1453|  } finally {
  1454|    if (timer) clearTimeout(timer);
  1455|  }
