  5696|      const res = await fetch(`${url}/rest/v1/${table}?select=${encodeURIComponent(col)}`, { method: 'HEAD', headers: { ...headers, Prefer: 'count=exact', Range: '0-0' } });
  5697|      if (res.status === 404) return { table, count: null, status: 404, error: 'TABLE_NOT_FOUND' };
  5698|      const cr = res.headers.get('content-range');
  5699|      const total = cr ? parseInt(cr.split('/').pop() || '*', 10) : null;
  5700|      return { table, count: Number.isFinite(total) ? total : null, status: res.status, error: null };
  5701|    } catch (e) {
