  5231|  if (!isCanonicalMembersConfigured()) {
  5232|    return Response.json({ ok: true, members: 0, waitlist: 0, investors: 0, buyers: 0, total: 0, timestamp: nowIso(), deploymentMarker: DEPLOYMENT_MARKER });
  5233|  }
  5234|  const all = await listCanonicalMembers({ limit: 5000 });
  5235|  const byType: Record<string, number> = {};
  5236|  for (const m of all) byType[m.member_type] = (byType[m.member_type] ?? 0) + 1;
  5237|  const members = (byType['member'] ?? 0) + (byType['user'] ?? 0);
  5238|  const waitlist = byType['waitlist'] ?? 0;
  5239|  const investors = byType['investor'] ?? 0;
  5240|  const buyers = byType['buyer'] ?? 0;
  5241|  return Response.json({
  5242|    ok: true,
  5243|    members,
  5244|    waitlist,
  5245|    investors,
  5246|    buyers,
  5247|    total: await countCanonicalMembers(),
  5248|    timestamp: nowIso(),
  5249|    deploymentMarker: DEPLOYMENT_MARKER,
  5250|  });
  5251|});
