  5715|// Never fabricates. If a table is missing or empty, it says so.
  5716|app.get('/api/ivx/visitor-audit', async () => {
  5717|  const url = (process.env.EXPO_PUBLIC_SUPABASE_URL || '').trim().replace(/\/+$/, '');
